/**
 * FRAME-CUT (TEACH-251 part f, heart R3 slide 8: "arm is good but it's cut off?"). A generated
 * picture can draw its subject past the edge of its own frame: the arm's fist ran off the top and
 * the shoulder off the left of a 3:2 picture shown whole in a 3:2 slot. No slide-side fit (cover,
 * crop window, contain on a matte) can restore pixels the model never drew, so the check runs on
 * the generated bytes, where a cut picture can still be made again.
 *
 * Only a picture on a plain backdrop is measured: one colour holds most of its edge, so any edge
 * pixel far from that colour is the subject touching the frame. A full-bleed scene (a farmyard, a forest) has no
 * backdrop, fills every edge by design and is never called cut.
 */
import { decodePng, type Raster } from "./panels";

export type FrameCut = {
  /** One backdrop colour holds most of the edge; false means a full-bleed scene, never measured. */
  plain: boolean;
  /** Per edge, the longest run of subject pixels along it, as a share of that edge's length. */
  edges: { top: number; right: number; bottom: number; left: number };
  /** The subject runs off the frame: some edge's run reaches `FRAME_CUT_RUN`. */
  cut: boolean;
  /** The sum of the edge runs: of two cut pictures, the smaller is the less cut. */
  bleed: number;
};

/** A subject run along one edge at least this share of it is a cut (3 %: past noise and fur tips). */
export const FRAME_CUT_RUN = 0.03;
/** A pixel this far (max channel) from the backdrop is subject. */
const TOL = 40;
/** A plain backdrop holds at least this share of the frame's edge; a full-bleed scene holds less. */
const PLAIN_SHARE = 0.6;

const far = (r: Raster, x: number, y: number, bg: readonly number[], tol: number) => {
  const i = (y * r.width + x) * 3;
  return (
    Math.max(
      Math.abs((r.rgb[i] ?? 0) - (bg[0] ?? 0)),
      Math.abs((r.rgb[i + 1] ?? 0) - (bg[1] ?? 0)),
      Math.abs((r.rgb[i + 2] ?? 0) - (bg[2] ?? 0)),
    ) > tol
  );
};

/**
 * The backdrop: the commonest colour round the frame's edge (quantised to 32 levels a channel) and
 * its share of the edge. A subject may run off a corner, so no single corner is trusted.
 */
function backdrop(r: Raster, edge: [number, number][]): { bg: number[]; share: number } {
  const buckets = new Map<number, { n: number; sum: [number, number, number] }>();
  for (const [x, y] of edge) {
    const i = (y * r.width + x) * 3;
    const c = [r.rgb[i] ?? 0, r.rgb[i + 1] ?? 0, r.rgb[i + 2] ?? 0] as const;
    const key = ((c[0] >> 5) << 6) | ((c[1] >> 5) << 3) | (c[2] >> 5);
    const b = buckets.get(key) ?? { n: 0, sum: [0, 0, 0] };
    b.n++;
    for (let k = 0; k < 3; k++) b.sum[k] = (b.sum[k] ?? 0) + (c[k] ?? 0);
    buckets.set(key, b);
  }
  let top = { n: 0, sum: [0, 0, 0] as [number, number, number] };
  for (const b of buckets.values()) if (b.n > top.n) top = b;
  return {
    bg: top.sum.map((v) => v / Math.max(1, top.n)),
    share: top.n / Math.max(1, edge.length),
  };
}

/** The longest run of subject pixels along a line of `n` points (`at(i)` gives each point). */
function run(n: number, hit: (i: number) => boolean): number {
  let best = 0;
  let cur = 0;
  for (let i = 0; i < n; i++) {
    cur = hit(i) ? cur + 1 : 0;
    if (cur > best) best = cur;
  }
  return best / n;
}

/** How far the subject of `r` runs off its frame (see the file note). */
export function frameCut(r: Raster): FrameCut {
  const w = r.width;
  const h = r.height;
  // One pixel in from each edge (the outermost row can carry a resampling seam).
  const at = {
    top: Array.from({ length: w }, (_, x) => [x, 1] as [number, number]),
    right: Array.from({ length: h }, (_, y) => [w - 2, y] as [number, number]),
    bottom: Array.from({ length: w }, (_, x) => [x, h - 2] as [number, number]),
    left: Array.from({ length: h }, (_, y) => [1, y] as [number, number]),
  };
  const { bg, share } = backdrop(r, [...at.top, ...at.right, ...at.bottom, ...at.left]);
  const plain = share >= PLAIN_SHARE;
  const none = { top: 0, right: 0, bottom: 0, left: 0 };
  if (!plain) return { plain, edges: none, cut: false, bleed: 0 };
  const line = (pts: [number, number][]) =>
    run(pts.length, (i) => far(r, ...(pts[i] as [number, number]), bg, TOL));
  const edges = {
    top: line(at.top),
    right: line(at.right),
    bottom: line(at.bottom),
    left: line(at.left),
  };
  const runs = Object.values(edges);
  return {
    plain,
    edges,
    cut: runs.some((v) => v >= FRAME_CUT_RUN),
    bleed: runs.reduce((a, v) => a + v, 0),
  };
}

/** `frameCut` of PNG bytes; undefined for anything that is not a PNG this decoder reads. */
export function frameCutOf(bytes: Uint8Array): FrameCut | undefined {
  try {
    return frameCut(decodePng(bytes));
  } catch {
    return undefined;
  }
}
